import pandas as pd
def clean(df):
    df = df.copy()
    # strip whitespace for text columns
    for col in ['Category', 'Region', 'Date']:
        if col in df.columns:
            df[col] = df[col].apply(lambda x: x.strip() if isinstance(x, str) else x)
    # normalize Category variants to allowed list
    cat_map = {
        'Accesories': 'Accessories',
        'electronics': 'Electronics',
        'Electornics': 'Electronics',
        'office supplies': 'Office Supplies',
        'Office Suplies': 'Office Supplies'
    }
    if 'Category' in df.columns:
        df['Category'] = df['Category'].replace(cat_map)
        allowed_lower = {'accessories': 'Accessories', 'electronics': 'Electronics', 'furniture': 'Furniture', 'office supplies': 'Office Supplies'}
        df['Category'] = df['Category'].apply(lambda x: allowed_lower.get(x.lower(), x) if isinstance(x, str) else x)
    # normalize Region (strip already done)
    if 'Region' in df.columns:
        df['Region'] = df['Region'].apply(lambda x: x.strip() if isinstance(x, str) else x)
    # parse Date, invalid becomes NaT
    if 'Date' in df.columns:
        df['Date'] = pd.to_datetime(df['Date'], errors='coerce')
    # ensure numeric types
    for col in ['Quantity', 'Price']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    # fix Revenue formula
    if 'Revenue' in df.columns and 'Quantity' in df.columns and 'Price' in df.columns:
        df['Revenue'] = df['Quantity'] * df['Price']
    return df

def answer(df):
    df = clean(df)
    # create month key YYYY-MM
    df['month'] = pd.to_datetime(df['Date'], errors='coerce').dt.strftime('%Y-%m')
    df = df.dropna(subset=['month'])
    grouped = df.groupby('month')['Revenue'].sum().sort_index()
    return {str(k): float(v) for k, v in grouped.items()}
